function numberToWords(num) {
  if (num === 0) {
    return 'Zero';
  }
  const ones = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];
  const tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
  const scales = ['', 'Thousand', 'Million', 'Billion'];

  function chunkWords(chunk) {
    const parts = [];
    if (chunk >= 100) {
      parts.push(ones[Math.floor(chunk / 100)], 'Hundred');
      chunk %= 100;
    }
    if (chunk >= 20) {
      parts.push(tens[Math.floor(chunk / 10)]);
      chunk %= 10;
    }
    if (chunk > 0) {
      parts.push(ones[chunk]);
    }
    return parts;
  }

  const words = [];
  for (let scale = scales.length - 1; scale >= 0; scale--) {
    const chunk = Math.floor(num / 1000 ** scale) % 1000;
    if (chunk === 0) {
      continue;
    }
    words.push(...chunkWords(chunk));
    if (scale > 0) {
      words.push(scales[scale]);
    }
  }
  return words.join(' ');
}

