function numberToWords(num) {
  // Recursive spelling: split off the largest scale, then spell both parts.
  const small = 'Zero One Two Three Four Five Six Seven Eight Nine Ten Eleven Twelve Thirteen Fourteen Fifteen Sixteen Seventeen Eighteen Nineteen'.split(' ');
  const decades = new Map([[2, 'Twenty'], [3, 'Thirty'], [4, 'Forty'], [5, 'Fifty'], [6, 'Sixty'], [7, 'Seventy'], [8, 'Eighty'], [9, 'Ninety']]);
  const big = [[1000000000, 'Billion'], [1000000, 'Million'], [1000, 'Thousand'], [100, 'Hundred']];
  function say(n) {
    if (n < 20) return small[n];
    if (n < 100) return decades.get(Math.floor(n / 10)) + (n % 10 ? ' ' + small[n % 10] : '');
    for (const [size, name] of big) {
      if (n >= size) return say(Math.floor(n / size)) + ' ' + name + (n % size ? ' ' + say(n % size) : '');
    }
  }
  return say(num);
}

