function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') return [2000000000 + pick(147483648)];
  const roll = rand();
  if (roll < 0.15) return [pick(120)];
  if (roll < 0.45) {
    // Build the number group by group so that zero groups and round values show up often.
    let num = 0;
    for (let group = 0; group < 4; group++) {
      const r = rand();
      const value = r < 0.35 ? 0 : r < 0.5 ? [1, 10, 19, 20, 100, 110, 900][pick(7)] : pick(1000);
      num = num * 1000 + (group === 0 ? value % 3 : value);
    }
    // Two billion plus a large remainder passes 2^31 - 1, so drop one billion in that case.
    return [num > 2147483647 ? num - 1000000000 : num];
  }
  const digits = 1 + pick(10);
  return [Math.min(2147483647, pick(10 ** digits))];
}
